        test('should generate unique UUIDs for multiple forEach loops', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-def-label-cache-foreach.now.ts')

            const flowRecords = merged['sys_hub_flow']
            const multipleForEachFlow = flowRecords.find(
                (flow: any) => flow.name === 'Flow - Label Cache ForEach Multiple'
            )
            expect(multipleForEachFlow).toBeDefined()

            const labelCache = JSON.parse(multipleForEachFlow.label_cache)

            // Get all forEach item data pills
            const forEachPills = labelCache.filter((pill: any) => pill.name.includes('.item.'))
            expect(forEachPills.length).toBeGreaterThan(0)

            // Extract UUIDs from forEach pills
            const uuids = new Set<string>()
            forEachPills.forEach((pill: any) => {
                const match = pill.name.match(/^([a-f0-9-]{36})\.item\./)
                if (match) {
                    uuids.add(match[1])
                }
            })

            // Should have 2 different UUIDs (one for each forEach loop)
            expect(uuids.size).toBe(2)

            // Check for department pills
            const deptNamePill = labelCache.find((pill: any) => pill.name.endsWith('.item.deptName'))
            expect(deptNamePill).toBeDefined()

            // Check for project pills
            const projectNamePill = labelCache.find((pill: any) => pill.name.endsWith('.item.projectName'))
            expect(projectNamePill).toBeDefined()

            // Verify they have different UUIDs
            const deptUuid = deptNamePill.name.match(/^([a-f0-9-]{36})/)?.[1]
            const projectUuid = projectNamePill.name.match(/^([a-f0-9-]{36})/)?.[1]
            expect(deptUuid).not.toBe(projectUuid)
        })

